# Single source of truth for the Python course curriculum (v4, 2026-11-21).
# T(num, title, goal, covers, sql, traps, practice)  - covers/traps/practice are ';'-separated.
def T(n, title, goal, covers, sql, traps, practice, status="planned"):
    sp = lambda s: [x.strip() for x in s.split(";") if x.strip()]
    return dict(n=n, title=title, goal=goal, covers=sp(covers), sql=sql, traps=sp(traps), practice=sp(practice), status=status)

MODULES = []
def M(code, title, outcome, topics, hours): MODULES.append(dict(code=code, title=title, outcome=outcome, topics=topics, hours=hours))

